<div class="page-actions"><div><h2>Event Management</h2><p>Create event pages with images, dates, times and locations. Publish or hide events without code changes.</p></div></div><div class="management-layout"><section class="admin-panel sticky-form"><div class="panel-head"><h3>Event Editor</h3><button class="outline-link mini" type="button" data-event-reset>New Event</button></div><form method="post" enctype="multipart/form-data" action="<?=url('admin/events/save')?>" class="admin-form" data-event-form><?=csrf_field()?><input type="hidden" name="id"><label class="full"><span>Event Title *</span><input name="title" required maxlength="180"></label><label><span>Event Date *</span><input type="date" name="event_date" required></label><label><span>Status</span><select name="status"><option value="draft">Draft</option><option value="published">Published</option><option value="completed">Completed</option><option value="cancelled">Cancelled</option></select></label><label><span>Start Time</span><input type="time" name="start_time"></label><label><span>End Time</span><input type="time" name="end_time"></label><label class="full"><span>Location</span><input name="location" maxlength="180"></label><label class="full"><span>Description</span><textarea name="description" rows="7" maxlength="30000"></textarea></label><label class="full"><span>Event Image</span><input type="file" name="image" accept=".jpg,.jpeg,.png,.webp"><small class="helper">Recommended 1200 × 800 px (3:2). Automatically cover-fitted.</small></label><label class="toggle-line full"><input type="checkbox" name="is_active" value="1" checked><span>Active / visible when published</span></label><button class="admin-btn full">Save Event</button></form></section><section class="event-admin-list"><?php foreach($events as $e):$payload=e(json_encode(['id'=>$e['id'],'title'=>$e['title'],'event_date'=>$e['event_date'],'status'=>$e['status'],'start_time'=>$e['start_time'],'end_time'=>$e['end_time'],'location'=>$e['location'],'description'=>$e['description'],'is_active'=>(int)$e['is_active']],JSON_HEX_APOS|JSON_HEX_QUOT));?><article class="event-admin-card admin-panel"><?php if($e['image_path']):?><img src="<?=e(public_upload($e['image_path']))?>" alt=""><?php else:?><div class="event-placeholder">◷</div><?php endif;?><div><span class="status-badge <?=e($e['status'])?>"><?=e(ucfirst($e['status']))?></span><h3><?=e($e['title'])?></h3><p><?=e(date('d M Y',strtotime($e['event_date'])))?> · <?=e($e['location']?:'Location TBA')?></p><div class="card-admin-actions"><button class="outline-link" type="button" data-event-edit='<?=$payload?>'>Edit</button><form method="post" action="<?=url('admin/events/delete')?>" data-confirm="Delete this event?"><?=csrf_field()?><input type="hidden" name="id" value="<?=$e['id']?>"><button class="danger-link">Delete</button></form></div></div></article><?php endforeach;?><?php if(!$events):?><div class="admin-panel empty-card">No events yet.</div><?php endif;?></section></div>

